WITH base AS (SELECT id, store_id, quantity, CASE WHEN quantity >= 200 THEN 'High' WHEN quantity >= 82 THEN 'Medium' ELSE 'Low' END quantity_level FROM inventory WHERE last_restock >= DATE '2023-08-09') SELECT id, quantity, SUM(quantity) OVER w_hist last7_sum_quantity, MAX(quantity) OVER w_hist last7_max_quantity, MIN(quantity) OVER w_hist last7_min_quantity, COUNT(quantity) OVER w_hist last7_count_quantity, NTILE(5) OVER (PARTITION BY store_id ORDER BY quantity ASC, id ASC) quantity_bucket FROM base WINDOW w_hist AS (PARTITION BY store_id ORDER BY quantity ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)
